static const char *wtr_lookup(const char *s, int l)
{
    if (!lang_ok(l)) return 0;
    for (unsigned i = 0; i < sizeof WTR / sizeof WTR[0]; i++) if (!strcmp(WTR[i][0], s)) return WTR[i][1 + l];
    return 0;
}
